namespace OpenTPW;

/// <summary>One value or rule that is not taken from original data or hard evidence.</summary>
public sealed record Approximation( string Id, string Area, string Assumption, string EvidenceNeeded );

/// <summary>
/// Register of the compatibility slice's approximations (tagged <c>[APPROX:COMPAT-NNN]</c> at each
/// site, listed in docs/COMPATIBILITY.md "Approximation register"). Logged once at startup so a
/// session log always states what is not original.
/// </summary>
public static class ApproximationRegister
{
	public static readonly IReadOnlyList<Approximation> Compatibility = new Approximation[]
	{
		new( "COMPAT-001", "Sign text", "The PC composes a 256x256 surface and packs only its top 128 rows into the two 128x128 textures (0x5ECB40 tail), as this port crops to 128 rows; the rows below 128 still feed the blur, morphology and relief neighbours at the seam natively and are not reproduced here, and the reduction of the 512-wide text DIB to the mask (0x5EAB70) is not read. Orientation (upright, unmirrored) and half order (sign1 left, sign2 right) match a PC v2.0 gameplay video.", "original-platform sign texture capture showing the lower DIB rows" ),
		new( "COMPAT-002", "Sign text", "The LOGFONT width is applied as a horizontal scale that makes the font's average character width (OS/2 xAvgCharWidth) equal lfWidth; the width search and centring are traced (0x100A9F9C). The Mac GDI layer's width rounding is not reproduced.", "captures of long ride names (the Mac GDI layer's width rounding)" ),
		new( "COMPAT-003", "Sign text", "Ride signs apply stored paint RGBA, source-image material strips, effect coefficients and native integer layer blending, and each paint mask is shaped as tp.exe 0x5EBF10 shapes it (offset copy 0x5EA3F0, erosion 0x5EA6D0 or dilation 0x5EA510 by the mask word +4, separable Gaussian 0x5EA8A0 by the parameter +8: Wilde Aap's drop shadow, the gate's shadow, Azteekse Tekens' outline). The relief strip resampler is tp.exe 0x5E80D0 (the Mac Bitmap::descimate twin: two bucket averages in 16.16 fixed point), which the strip resampling matches (its missing upsampling branch is [EXT:sign-relief-upsample]). Open: the blur kernels run in x87 extended precision (0x5EA8A0: exp(-r^2 / 2 sigma^2) / (sigma^2 x 6.2831853), normalised) where this port uses doubles, the relief reads the right and lower neighbours of a mask row without clamping (0x5EB8A0), and the original GDI glyph coverage.", "a capture on a machine where the sign fonts load" ),
		new( "COMPAT-004", "Sign text", "The gate is composed from its decoded board with the park name as two lines (as the original draws them) and the stored paint (a 60 % black shadow under dark relief stone text, as in the video); gate pixels (board placement, relief strength) are compared with a 720p capture only.", "original-platform gate capture at the native resolution" ),
		new( "COMPAT-006", "Sign text", "No pair kerning on signs: tp.exe has no TextOut/DrawText/ExtTextOut imports, its sign text goes through Uniscribe (0x5EAB70) and no kerning API is called; every shipped sign font has only the legacy kern table (464 to 12,657 pairs) and no GPOS or GSUB table.", "whether the classic Uniscribe path (ScriptShape and ScriptPlace behind ScriptStringAnalyse) applies a legacy kern table to the natural widths ScriptStringGetLogicalWidths returns (usp10.dll is not among the binaries in scope)" ),
		new( "COMPAT-007", "Sign text", "The park name is the gate's two sign lines: they start as the gate's OBJECT_NAMES row (0x4DB6F9), the entry price window's rename dialog (0x4990F0, OK 0x4993E0) stores them and redraws the gate, and OpenTPW's world save keeps them. The OK handler's other effects are not built: the copies to the online park record (0x409410, 0x5B0940/0x5B0970, +0x34/+0x76 of the 0x50-byte record DAT_00F7C58C, unless GameType is 1) and the secret name compared with 0x751A34/0x751A38 (\"Kevin the\" / \"Cosmic Cow\"), which calls 0x4053C0(1): it stores a flag on the object 0xFB3520 (saved by 0x4164C0, loaded by 0x415270, read at 0x488902/0x488991) and dispatches event type 0x15. Gate lines of a user-supplied original save are not imported (the attraction record carries them; the shipped Easymode save holds the default row).", "what the listeners of event 0x15 and the object 0x78733C that the flag forwards to do" ),
		new( "COMPAT-018", "Sign text", "The native wavelet container and board alpha blit are implemented for ride signs; final GPU row orientation and original-platform board appearance remain unverified. tp.exe compares the BILZ chunk tag at 0x6193D0 (the inflate step); its inverse transform is read: the D4 coefficients are computed at start-up (0x591600..0x591690), the 1-D inverse 0x592C50 has the decoder's formulas (only the summation order differs, one float ulp), and the YCbCr conversion 0x5935A0 rounds each colour sum to a whole number through the 1.5 x 2^23 magic number and a 512-entry clamp table (0x5916C0), as the decoder now does; still open: where the header scale enters the 2-D driver 0x592E60 (the decoder applies it in the row pass), the alpha channel's conversion, the x87 precision control at the conversion (24 or 64 bit mantissa: one level on a few pixels) and an original ride-sign capture", "the scale position in 0x592E60, the alpha conversion, the FPU precision control, independent native bitmap pixels and an original ride-sign capture" ),
		new( "COMPAT-032", "Sign text", "In the original a textured face's state word follows its texture's alpha type (0x581790 -> 0x590C40, texture flags +8 & 0x300: 0x100 alpha blend with an alpha test at 0xF0/255 (0x2756), 0x200 alpha blend with an alpha test at 0x10/255 (0x556), 0x300 source-alpha-over-one (0x200552), else opaque (0x1256)), all with depth writes (decoder 0x567620), and the batcher 0x581DB0 orders by state and texture; OpenTPW draws the faces with its own alpha test and blend (an extension); which alpha type the generated sign texture carries, and so which state word the original would use, is not read.", "the alpha type of the generated sign texture and a distant capture" ),
		new( "COMPAT-010", "Graphics presets", "tp.exe's option apply 0x44D8F0 sets engine flag 0x20000 for option [0x785898] = 0 and 0x40000 for 1 (neither for 2 and 3), and its state decoder 0x567620 sets stage 0 from the state word: 0x20000 -> MAGFILTER point (else linear), 0x40000 -> MIPFILTER none (else the device's mode 1-3 chosen by caps at 0x566840), 0x400000 -> wrap addressing with a linear MINFILTER (else clamp with a point MINFILTER); the table position of the variables (base 0x785874 + 4 x option index, anchored by the five-valued SKYQUALITY at [0x785888] and the four-valued FIRSTPERSONVIEWDISTANCE at [0x7858B4]) makes [0x785898] the tenth option, SPRITESHADOW, and TEXTUREFILTERING [0x785878] (it only clears or sets bits 0x18 of DAT_008BD550); the registration that binds option names to these variables, which option the engine's filter bits belong to and how the engine flags reach a primitive's state word are not read.", "the registration that binds option names to the variables at 0x785878.. and the path from the engine flags 0x8BCBC8 into the state word" ),
	};

	/// <summary>Logs every approximation once.</summary>
	public static void LogAll( Action<string> warn )
	{
		ArgumentNullException.ThrowIfNull( warn );
		foreach ( var entry in Compatibility )
			warn( $"[APPROX:{entry.Id}] {entry.Area}: {entry.Assumption} Evidence needed: {entry.EvidenceNeeded}." );
	}
}
